#!/usr/bin/env python3
"""Read-only Hy naming inventory for HyRemote (#969 P0).

Scope: reads tracked files only and writes three report files next to this
script. It never edits product sources, CMake files, tests, docs content or CI
configuration, and it never starts a Qt build or a test suite.

Script contract (declared in the #969 P0 task plan before this file existed):
  name: docs/internal/scan_hy_naming_inventory.py (P0 generator only).
        The source is archived in hy-naming-inventory.json#generator_source.
        This file is NOT committed as a tracked script: the script register
        tests/release-readiness/script_inventory.txt belongs to #975's tests/
        scope, which this read-only P0 turn must not edit.
  purpose: produce the machine-readable naming inventory, the existing ->
           proposed mapping and the machine-check statistics that support the
           P0 read-only decision.
  inputs: --root (repository root), --base-sha, tracked files from git.
  outputs: docs/internal/hy-naming-inventory.csv
           docs/internal/hy-naming-inventory.json
           docs/internal/hy-naming-audit-summary.json
  reuse: no existing tracked .py performs a naming inventory; the nearest
         docs/check_ai_flavor.py inspects prose style only.
  registration: P0 is READ_ONLY and deliberately not registered in CTest/CI;
                #972 owns .github/ and #975 owns tests/ and tools/test/.
  run count: one --self-test plus one real scan during P0.
  PASS: 12 required columns present, every tracked src/ C++/CMake/QML file
        covered, self-test positive and negative cases pass, no absolute
        local path appears in any output.
"""

from __future__ import annotations

import argparse
import csv
import json
import re
import subprocess
import sys
from collections import Counter, defaultdict
from pathlib import Path

REQUIRED_FIELDS = [
    "current_file", "current_type", "namespace", "layer",
    "public_or_private", "target_name", "ABI_impact", "source_impact",
    "QML_impact", "build_impact", "test_impact", "migration_phase",
]
EXTRA_FIELDS = [
    "kind", "proposed_name", "proposed_file", "name_file_match",
    "exemption", "rationale",
]
FIELDS = REQUIRED_FIELDS + EXTRA_FIELDS

CPP_EXT = {".h", ".hpp", ".cpp", ".cc", ".cxx", ".c"}
CMAKE_EXT = {".txt", ".cmake", ".in"}
TEXT_EXT = CPP_EXT | CMAKE_EXT | {".json", ".qml", ".yml", ".yaml",
                                 ".cmd", ".sh", ".md", ".py"}

QT_TYPE_RE = re.compile(r"\b(Q[A-Z][a-z][A-Za-z0-9_]*)\b")
HY_MACRO_RE = re.compile(r"\b(HYREMOTE_[A-Z0-9_]+)\b")
EXPORT_MACRO_RE = re.compile(r"\b(HYREMOTE_[A-Z0-9_]*_EXPORT)\b")
NS_RE = re.compile(
    r"\bnamespace\s+([A-Za-z_][A-Za-z0-9_]*(?:::[A-Za-z_][A-Za-z0-9_]*)*)\s*\{"
)
DECL_RE = re.compile(
    r"\b(class|struct|enum\s+class|enum)\s+"
    r"(?:[A-Z][A-Z0-9_]*_EXPORT\s+)?([A-Za-z_][A-Za-z0-9_]*)\b"
)
ALIAS_RE = re.compile(r"\busing\s+([A-Z][A-Za-z0-9_]*)\s*=")
INCLUDE_RE = re.compile(r"#include\s+[<\"]([^>\"]+)[>\"]")
TARGET_CALL_RE = re.compile(
    r"\b(add_library|add_executable|add_custom_target|qt_add_qml_module|"
    r"qt_add_plugin|target_sources)\s*\(\s*([^\s\)]+)"
)
TEST_NAME_RE = re.compile(r"\badd_test\s*\(\s*(?:NAME\s+)?([A-Za-z0-9_.\-]+)")
URI_RE = re.compile(r"\bURI\s+([A-Za-z][A-Za-z0-9_.]*)")
QML_ELEMENT_RE = re.compile(r"\bQML_(?:NAMED_)?ELEMENT\s*(?:\(\s*([A-Za-z_]\w*)\s*\))?")
PLUGIN_TOKEN_RE = re.compile(
    r"(qhyremote|-plugin\s+hyremote|-platform\s+hyremote|hyremote\.json)"
)
C_API_RE = re.compile(r"\b(hyremote_[a-z0-9_]+)\s*\(")
SOURCE_TOKEN_RE = re.compile(r"[A-Za-z0-9_.\-/]+\.(?:cpp|h|hpp|c|cc|qml)")
PUBLIC_HEADER_PREFIX = "src/integrations/cpp/include/"

MODULE_PREFIXES = {
    "quick", "widget", "widgets", "rfb", "vnc", "qml", "generic", "qpa",
    "native", "automatic", "detail", "transport", "capture", "input",
    "watermark", "host", "runtime", "session", "frame", "test",
}
NESTED_NAMES = {"Impl", "State", "Pending", "Route", "FrontendError"}

PUBLIC_TOKENS = [
    "HyRemote::RemoteAccess", "HyRemote/RemoteAccess.h",
    "find_package(HyRemote", "HyRemote::RemoteAccess",
    "HyRemoteRemoteAccess", "import HyRemote", "hyremote_deploy",
    "QML_NAMED_ELEMENT(RemoteAccess)", "qhyremote",
    "-plugin hyremote", "-platform hyremote",
]

FROZEN_PHASE = "frozen-contract"
FROZEN_KINDS = {
    "cmake_target", "cmake_alias", "cmake_option", "export_macro",
    "qml_uri", "qml_element", "test_identity", "c_api_symbol",
    "wire_file", "plugin_token", "plugin_manifest", "namespace",
    "doc_reference", "third_party_type", "third_party_macro",
}


def is_qt_type(name: str) -> bool:
    return bool(QT_TYPE_RE.fullmatch(name))


def to_hy(name: str) -> str:
    if not re.fullmatch(r"[A-Z][A-Za-z0-9_]*", name):
        raise ValueError("not a PascalCase type name: %r" % name)
    return name if name.startswith("Hy") else "Hy" + name


def hy_stem(name: str) -> str:
    body = name[2:] if name.startswith("Hy") else name
    return "hy" + body.lower()


def snake(name: str) -> str:
    first = re.sub(r"(.)([A-Z][a-z]+)", r"\1_\2", name)
    return re.sub(r"([a-z0-9])([A-Z])", r"\1_\2", first).lower()


def legacy_match(stem: str, class_name: str) -> bool:
    return stem == snake(class_name) or stem == class_name


def resolve_main_class(stem, class_by_stem):
    """Return (class_name, match_kind) for one source file stem."""
    if stem in class_by_stem:
        return class_by_stem[stem], "legacy-conformant"
    stem_tokens = set(stem.split("_"))
    candidates = []
    for snake_name, name in class_by_stem.items():
        class_tokens = set(snake_name.split("_"))
        extra = stem_tokens - class_tokens
        if class_tokens == stem_tokens or (class_tokens < stem_tokens
                                           and len(extra) == 1
                                           and extra <= MODULE_PREFIXES):
            candidates.append(name)
    if candidates:
        return max(candidates, key=len), "module-prefix-mismatch"
    return None, "no-primary-class"


def is_repo_relative(path: str) -> bool:
    if not path or path.startswith("/") or "\\" in path:
        return False
    if re.match(r"^[A-Za-z]:[\\/]", path):
        return False
    return not path.startswith("../")


def is_safe_output_dir(path: str) -> bool:
    if not is_repo_relative(path):
        return False
    head = path.split("/")[0]
    return head == "docs" and not path.startswith("docs/en/")


def propose_for(name, kind, private=False, impl=False, owner=None):
    """Return (proposed_name, proposed_file). 'unchanged' means keep as is."""
    if kind in FROZEN_KINDS or is_qt_type(name):
        return ("unchanged", "unchanged")
    if not re.fullmatch(r"[A-Z][A-Za-z0-9_]*", name):
        return ("unchanged", "unchanged")
    if kind == "pimpl" and owner:
        base = to_hy(owner)
        return (base + "Private", hy_stem(base) + "_p.h")
    new_name = to_hy(name)
    if private:
        return (new_name, hy_stem(new_name) + "_p.h")
    if impl:
        return (new_name, hy_stem(new_name) + ".cpp")
    return (new_name, hy_stem(new_name) + ".h")


def strip_cpp(text: str) -> str:
    text = re.sub(r"/\*.*?\*/", " ", text, flags=re.S)
    return re.sub(r"//[^\n]*", " ", text)


def strip_hash(text: str) -> str:
    return re.sub(r"#[^\n]*", " ", text)


def call_body(text: str, start: int) -> str:
    depth = 1
    i = start
    while i < len(text) and depth:
        if text[i] == "(":
            depth += 1
        elif text[i] == ")":
            depth -= 1
        i += 1
    return text[start:max(start, i - 1)]


def layer_of(rel: str) -> str:
    if rel.startswith("tests/") or "/tests/" in rel:
        return "tests"
    if rel.startswith("src/core/"):
        return "core"
    if rel.startswith("src/runtime/"):
        return "runtime"
    if rel.startswith("src/integrations/cpp/"):
        return "integrations-cpp"
    if rel.startswith("src/integrations/qml/"):
        return "integrations-qml"
    if rel.startswith("src/integrations/generic/"):
        return "integrations-generic"
    if rel.startswith("src/integrations/qpa/"):
        return "integrations-qpa"
    if rel.startswith("examples/"):
        return "examples"
    if rel.startswith("docs/"):
        return "docs"
    if rel.startswith("tools/"):
        return "tools"
    if rel.startswith(".github/"):
        return "governance"
    if rel.startswith("cmake/") or rel.endswith(("CMakeLists.txt", ".cmake")):
        return "build"
    return "root"


def public_of(rel: str, layer: str) -> str:
    if rel.startswith(PUBLIC_HEADER_PREFIX):
        return "public-installed"
    if rel.startswith("src/core/include/"):
        return "internal-core-api"
    if rel.startswith("src/") and "/include/" in rel:
        return "module-public-header"
    if "/detail/" in rel or rel.endswith(("_p.h", "_p.hpp", "_p_p.h", "_p_p.hpp")):
        return "private"
    if layer in ("build", "governance", "docs", "examples", "tests", "tools"):
        return layer
    if rel.startswith("src/"):
        return "internal"
    return "root"


def decide(kind, layer, public):
    """Return impacts, migration phase, exemption and rationale for one row."""
    if kind in ("third_party_type", "third_party_macro"):
        return ("none", "none", "none", "none", "none", "exempt-third-party",
                "qt-owned-symbol", "Qt-owned symbol; never renamed or wrapped")
    if kind == "public_type":
        return ("abi-break-if-renamed", "consumer-source-break", "none",
                "export-symbol+install-path",
                "installed-consumer+example+ctest-identity", "human-decision",
                "no", "Installed SDK type on the docs/v1-api-stability.md stable surface")
    if kind == "pimpl":
        return ("none (private)", "private-header-only", "none", "moc-none",
                "none", "P1", "no",
                "Nested pimpl; proposed HyFooPrivate in hyfoo_p.h, not installed")
    if kind == "namespace":
        return ("abi-break-if-changed", "wide-include-change", "none", "none",
                "wide", "human-decision", "no",
                "Two namespaces are deliberate; convergence needs source/ABI cost analysis")
    if kind in ("qml_uri", "qml_element", "plugin_token", "plugin_manifest"):
        return ("none", "none", "qml-break-uri-or-type", "deploy-contract-rename",
                "installed-qml/generic/qpa-product-fit", "human-decision",
                "deploy-or-qml-contract",
                "Public QML URI/type or documented zero-code activation token")
    if kind in ("cmake_target", "cmake_alias", "cmake_option", "export_macro"):
        return ("none", "none", "none", "cmake-contract-rename",
                "build-authority+readiness-gate", FROZEN_PHASE,
                "build-contract",
                "Existing build/export contract; the convention keeps it unchanged")
    if kind == "test_identity":
        return ("none", "none", "none", "none", "ctest-identity+evidence",
                FROZEN_PHASE, "test-evidence-identity",
                "#970 reuse; identity is evidence, no per-file new CTest")
    if kind in ("c_api_symbol", "wire_file"):
        return ("c-abi-break", "none", "none", "none", "wire-evidence",
                FROZEN_PHASE, "c-api-or-wire",
                "C ABI / RFB wire / historical evidence identity is frozen")
    if kind == "doc_reference":
        return ("none", "none", "none", "none", "none", "P3", "no",
                "Documentation follows an accepted versioned migration")
    if public == "internal-core-api":
        return ("internal-abi (core/static)", "internal-include-path", "none",
                "cmake-source-list", "module-tests", "P2", "no",
                "Core contract is not installed as an SDK but is cross-module")
    if kind == "private_type" or public == "private":
        return ("none (private)", "internal-include-path", "none",
                "cmake-source-list+moc", "module-tests", "P1", "no",
                "Private Runtime detail; the low-risk demonstration group")
    if layer in ("examples", "docs"):
        return ("none", "consumer-source-break-if-api-changes", "none", "none",
                "example-smoke", "P3", "no",
                "Consumer-side reference; follows the accepted migration")
    return ("none", "internal-include-path", "none", "cmake-source-list",
            "module-tests", "P2", "no",
            "Internal implementation symbol; batch by component in P2")


def make_row(current_file, current_type, namespace, layer, public, target_name,
             kind, proposed_name, proposed_file, match="n/a"):
    abi, source, qml, build, test, phase, exemption, rationale = decide(
        kind, layer, public)
    return {
        "current_file": current_file,
        "current_type": current_type,
        "namespace": namespace or "-",
        "layer": layer,
        "public_or_private": public,
        "target_name": target_name or "-",
        "ABI_impact": abi,
        "source_impact": source,
        "QML_impact": qml,
        "build_impact": build,
        "test_impact": test,
        "migration_phase": phase,
        "kind": kind,
        "proposed_name": proposed_name,
        "proposed_file": proposed_file,
        "name_file_match": match,
        "exemption": exemption,
        "rationale": rationale,
    }


def tracked_files(root: Path):
    result = subprocess.run(["git", "ls-files"], cwd=str(root),
                            capture_output=True, text=True, check=True)
    return sorted({line.strip().replace("\\", "/")
                   for line in result.stdout.splitlines() if line.strip()})


def in_scan_scope(rel: str) -> bool:
    if rel.startswith(("tmp/", "build/")):
        return False
    if rel.startswith(("src/", "examples/", "cmake/", "tests/", "docs/",
                       "tools/", ".github/")):
        return True
    return "/" not in rel and Path(rel).suffix in TEXT_EXT


def read_text(root: Path, rel: str) -> str:
    try:
        return (root / rel).read_text(encoding="utf-8", errors="replace")
    except OSError:
        return ""


def build_target_index(root, paths):
    target_by_basename = defaultdict(set)
    targets = []
    for rel in paths:
        if not (rel.endswith("CMakeLists.txt") or rel.endswith(".cmake")
                or rel.endswith(".cmake.in")):
            continue
        body = strip_hash(read_text(root, rel))
        for match in TARGET_CALL_RE.finditer(body):
            name = match.group(2)
            chunk = call_body(body, match.end())
            for token in SOURCE_TOKEN_RE.findall(chunk):
                target_by_basename[Path(token).name].add(name)
            kind = "cmake_alias" if "::" in name else "cmake_target"
            targets.append((rel, name, kind))
    return target_by_basename, targets


def collect(root: Path, base_sha: str):
    all_paths = tracked_files(root)
    scope = [p for p in all_paths if in_scan_scope(p)]
    target_index, target_entries = build_target_index(root, scope)
    targets_by_file = defaultdict(list)
    for rel, name, kind in target_entries:
        targets_by_file[rel].append((name, kind))

    rows = []
    qt_type_first = {}
    ns_first = {}
    plugin_token_first = {}
    c_api_first = {}
    qt_plugin_metadata_files = []
    type_locations = defaultdict(set)
    own_types = 0
    hy_types = 0
    own_files = 0
    hy_files = 0
    legacy_matches = 0
    mapping_counts = Counter()
    mismatch_examples = []
    private_headers = []
    private_p_suffix = 0
    guard_stats = Counter()
    moc_files = []
    automoc_files = []
    public_headers = []
    public_header_includes = {}
    ctest_identities = set()
    cmake_targets = set()
    cmake_options = set()
    export_macros = set()
    qml_registrations = []
    install_rules = []
    wire_files = []
    doc_refs = defaultdict(lambda: {"count": 0, "files": set()})

    class_by_stem = {}
    for rel in scope:
        if Path(rel).suffix not in CPP_EXT or not rel.startswith("src/"):
            continue
        if "/tests/" in rel:
            continue
        body = strip_cpp(read_text(root, rel))
        for _, name in DECL_RE.findall(body):
            if is_qt_type(name) or name in NESTED_NAMES:
                continue
            class_by_stem.setdefault(snake(name), name)

    for rel in scope:
        suffix = Path(rel).suffix
        if suffix not in TEXT_EXT and not rel.endswith("CMakeLists.txt"):
            continue
        raw = read_text(root, rel)
        body = strip_cpp(raw) if suffix in CPP_EXT else strip_hash(raw)
        layer = layer_of(rel)
        public = public_of(rel, layer)
        target_names = ";".join(sorted(
            target_index.get(Path(rel).name, set()))) or "-"

        if layer != "docs":
            for match in QT_TYPE_RE.finditer(body):
                name = match.group(1)
                if name not in qt_type_first or (
                        rel.startswith("src/")
                        and not qt_type_first[name].startswith("src/")):
                    qt_type_first[name] = rel

        for token in PUBLIC_TOKENS:
            count = raw.count(token)
            if count and layer == "docs":
                doc_refs[token]["count"] += count
                doc_refs[token]["files"].add(rel)

        if suffix in CPP_EXT:
            if rel.startswith(PUBLIC_HEADER_PREFIX) and suffix in (".h", ".hpp"):
                public_headers.append(rel)
                public_header_includes[rel] = INCLUDE_RE.findall(raw)
            if rel.startswith("src/") and "/detail/" in rel:
                private_headers.append(rel)
            if rel.endswith(("_p.h", "_p.hpp", "_p_p.h", "_p_p.hpp")):
                private_headers.append(rel)
                private_p_suffix += 1
            if suffix in (".h", ".hpp") and rel.startswith("src/"):
                if "#pragma once" in raw:
                    guard_stats["pragma_once"] += 1
                elif re.search(r"#ifndef\s+[A-Z0-9_]+_H", raw):
                    guard_stats["ifndef_guard"] += 1
                else:
                    guard_stats["missing"] += 1
            if "Q_OBJECT" in raw or "QML_NAMED_ELEMENT" in raw:
                moc_files.append(rel)
            if "Q_PLUGIN_METADATA" in raw:
                qt_plugin_metadata_files.append(rel)
            if "extern \"C\"" in raw:
                for symbol in C_API_RE.findall(raw):
                    c_api_first.setdefault(symbol, rel)

            ns_here = (sorted(set(NS_RE.findall(body)))
                       if rel.startswith("src/") else [])
            for ns in ns_here:
                ns_first.setdefault(ns, rel)
            primary_ns = ns_here[0] if ns_here else "-"

            decls = list(DECL_RE.findall(body))
            decls += [("using", name) for name in ALIAS_RE.findall(body)]

            if layer not in ("tests", "examples", "docs", "tools"):
                for decl_kind, name in decls:
                    if is_qt_type(name):
                        continue
                    if name in NESTED_NAMES:
                        if name == "Impl" and rel.startswith(PUBLIC_HEADER_PREFIX):
                            prop_name, prop_file = propose_for(
                                "Impl", "pimpl", owner=Path(rel).stem)
                            rows.append(make_row(
                                rel, "Impl", primary_ns, layer, "private",
                                target_names, "pimpl", prop_name, prop_file))
                        continue
                    own_types += 1
                    if name.startswith("Hy"):
                        hy_types += 1
                    type_locations[name].add((primary_ns, layer))
                    kind = ("public_type" if public == "public-installed"
                            else "private_type" if public == "private"
                            else "internal_type")
                    if decl_kind == "using":
                        kind = "alias"
                    prop_name, prop_file = propose_for(
                        name, kind, private=(public == "private"),
                        impl=(suffix == ".cpp"))
                    rows.append(make_row(
                        rel, name, primary_ns, layer, public, target_names,
                        kind, prop_name, prop_file))

            if rel.startswith("src/"):
                stem = Path(rel).stem
                if "/tests/" in rel:
                    rows.append(make_row(
                        rel, Path(rel).name, primary_ns, layer, public,
                        target_names, "file", "unchanged", "unchanged",
                        match="test-file"))
                else:
                    own_files += 1
                    main_class, match_kind = resolve_main_class(
                        stem, class_by_stem)
                    mapping_counts[match_kind] += 1
                    if main_class:
                        is_hy = stem in (hy_stem(to_hy(main_class)),
                                         hy_stem(to_hy(main_class)) + "_p")
                        if is_hy:
                            mapping_counts[match_kind] -= 1
                            mapping_counts["hy-conformant"] += 1
                            match_kind = "hy-conformant"
                        hy_files += 1 if is_hy else 0
                        if match_kind == "legacy-conformant":
                            legacy_matches += 1
                        if match_kind == "module-prefix-mismatch":
                            mismatch_examples.append(
                                {"file": rel, "class": main_class})
                        prop_name, prop_file = propose_for(
                            main_class, "internal_type",
                            impl=(suffix == ".cpp"))
                        rows.append(make_row(
                            rel, Path(rel).name, primary_ns, layer, public,
                            target_names, "file", prop_name, prop_file,
                            match=match_kind))
                    else:
                        rows.append(make_row(
                            rel, Path(rel).name, primary_ns, layer, public,
                            target_names, "file", "unchanged", "unchanged",
                            match=match_kind))

        if rel.startswith("src/") and suffix in (".qml", ".json"):
            rows.append(make_row(
                rel, Path(rel).name, "-", layer, public, target_names,
                "file", "unchanged", "unchanged", match="not-cxx"))

        if rel.endswith(("CMakeLists.txt", ".cmake", ".cmake.in")):
            for name, kind in targets_by_file[rel]:
                cmake_targets.add(name)
                rows.append(make_row(
                    rel, name, "-", "build", "build", name, kind,
                    "unchanged", "unchanged"))
            for macro in sorted(set(HY_MACRO_RE.findall(body))):
                if macro.endswith("_EXPORT"):
                    export_macros.add(macro)
                    rows.append(make_row(
                        rel, macro, "-", "build", "build", "-",
                        "export_macro", "unchanged", "unchanged"))
                else:
                    cmake_options.add(macro)
                    rows.append(make_row(
                        rel, macro, "-", "build", "build", "-",
                        "cmake_option", "unchanged", "unchanged"))
            for test_name in sorted(set(TEST_NAME_RE.findall(body))):
                ctest_identities.add(test_name)
                rows.append(make_row(
                    rel, test_name, "-", "tests", "tests", "-",
                    "test_identity", "unchanged", "unchanged"))
            if "CMAKE_AUTOMOC" in body or "qt_add_qml_module" in body:
                automoc_files.append(rel)
            for uri in sorted(set(URI_RE.findall(body))):
                qml_registrations.append({"file": rel, "name": uri,
                                          "kind": "URI"})
                rows.append(make_row(
                    rel, uri, "-", layer, "qml-public", "-", "qml_uri",
                    "unchanged", "unchanged"))
            if "install(" in body and "include" in body:
                install_rules.append(rel)

        for macro in sorted(set(EXPORT_MACRO_RE.findall(raw))):
            if suffix in CPP_EXT:
                export_macros.add(macro)
                rows.append(make_row(
                    rel, macro, "-", layer, public, "-", "export_macro",
                    "unchanged", "unchanged"))

        if suffix in CPP_EXT:
            for element in QML_ELEMENT_RE.findall(body):
                if element:
                    qml_registrations.append({"file": rel, "name": element,
                                              "kind": "QML_ELEMENT"})
                    rows.append(make_row(
                        rel, element, "-", layer, "qml-public", "-",
                        "qml_element", "unchanged", "unchanged"))

        for token in set(PLUGIN_TOKEN_RE.findall(body)):
            plugin_token_first.setdefault(token, rel)

        if suffix == ".json" and "hyremote" in Path(rel).name:
            rows.append(make_row(
                rel, Path(rel).name, "-", layer, "plugin-public", "-",
                "plugin_manifest", "unchanged", "unchanged"))

        if rel.startswith("src/runtime/src/transport/") and suffix in CPP_EXT:
            wire_files.append(rel)
            rows.append(make_row(
                rel, Path(rel).name, "-", layer, "wire", "-", "wire_file",
                "unchanged", "unchanged"))

    for token, rel in sorted(plugin_token_first.items()):
        rows.append(make_row(
            rel, token, "-", layer_of(rel), "plugin-public", "-",
            "plugin_token", "unchanged", "unchanged"))
    for rel in sorted(set(qt_plugin_metadata_files)):
        rows.append(make_row(
            rel, "Q_PLUGIN_METADATA", "-", layer_of(rel), "third-party",
            "-", "third_party_macro", "unchanged", "unchanged"))
    for symbol, rel in sorted(c_api_first.items()):
        rows.append(make_row(
            rel, symbol, "-", "tests", "c-api", "-", "c_api_symbol",
            "unchanged", "unchanged"))
    for name, rel in sorted(qt_type_first.items()):
        rows.append(make_row(
            rel, name, "-", "third-party", "third-party", "-",
            "third_party_type", "unchanged", "unchanged"))
    for ns, rel in sorted(ns_first.items()):
        rows.append(make_row(
            rel, ns, ns, "cross-layer", "mixed", "-", "namespace",
            "unchanged", "unchanged"))
    for token, info in sorted(doc_refs.items()):
        rows.append(make_row(
            "docs/", token, "-", "docs", "docs", "-", "doc_reference",
            "unchanged", "unchanged"))

    case_groups = defaultdict(set)
    for rel in all_paths:
        case_groups[rel.lower()].add(rel)
    case_collisions = sorted([sorted(v) for v in case_groups.values() if len(v) > 1])

    duplicates = {name: sorted([list(x) for x in locs])
                  for name, locs in type_locations.items() if len(locs) > 1}

    leaks = [
        {"file": rel, "include": inc}
        for rel, includes in public_header_includes.items()
        for inc in includes
        if "detail/" in inc or inc.endswith(("_p.h", "_p.hpp"))
        or inc.startswith("src/") or inc.startswith("hyremote/core/")
    ]

    public_sensitive = sorted({
        row["current_type"] for row in rows
        if row["kind"] in ("public_type", "qml_uri", "qml_element",
                           "plugin_token", "plugin_manifest")
        and not is_qt_type(row["current_type"])
        and row["current_file"].startswith("src/")
    })

    rows.sort(key=lambda r: (r["current_file"], r["kind"], r["current_type"]))

    by_kind = Counter(row["kind"] for row in rows)
    by_layer = Counter(row["layer"] for row in rows)
    by_phase = Counter(row["migration_phase"] for row in rows)
    renamable = sum(1 for row in rows if row["proposed_name"] != "unchanged")

    own_type_rate = round(1.0 - (hy_types / own_types), 4) if own_types else 0.0
    own_file_rate = round(1.0 - (hy_files / own_files), 4) if own_files else 0.0
    with_class = mapping_counts["legacy-conformant"] + \
        mapping_counts["module-prefix-mismatch"] + mapping_counts["hy-conformant"]
    legacy_rate = round(legacy_matches / with_class, 4) if with_class else 0.0

    summary = {
        "schema": "hy-naming-audit-summary/v0.1",
        "issue": 969,
        "phase": "P0",
        "test_plan": "READ_ONLY",
        "base_sha": base_sha,
        "generated_by": "hy-naming-inventory.json#generator_source",
        "edit_scope": ["docs/internal/"],
        "out_of_edit_scope": ["src/", "tests/", "tools/test/", ".github/",
                              "cmake/", "examples/"],
        "scope_note": (
            "All tracked paths are checked for case-insensitive collisions. "
            "Symbol extraction covers src/, examples/, cmake/, tests/, docs/, "
            "tools/ and .github/. Local helper types inside tests/ and examples/ "
            "are not product symbols and are not expanded into inventory rows."
        ),
        "counts": {
            "tracked_files": len(all_paths),
            "scanned_files": len(scope),
            "inventory_rows": len(rows),
            "by_kind": dict(sorted(by_kind.items())),
            "by_layer": dict(sorted(by_layer.items())),
            "by_migration_phase": dict(sorted(by_phase.items())),
            "renamable_rows": renamable,
        },
        "conformance": {
            "own_cxx_types": own_types,
            "hy_prefixed_types": hy_types,
            "hy_prefix_violation_rate": own_type_rate,
            "own_src_cxx_files": own_files,
            "hy_named_files": hy_files,
            "hy_filename_violation_rate": own_file_rate,
            "files_with_primary_class": with_class,
            "legacy_name_file_matches": legacy_matches,
            "legacy_name_file_match_rate_of_files_with_primary_class": legacy_rate,
            "interpretation": (
                "The current tree is internally consistent with "
                "docs/internal/naming-conventions.md (snake_case files vs "
                "PascalCase types, plus the installed PascalCase header). The "
                "high Hy-prefix violation rate measures distance from the "
                "*proposed* convention, not existing defects."
            ),
        },
        "file_mapping": {
            "breakdown": dict(sorted(mapping_counts.items())),
            "module_prefix_mismatch_examples": sorted(
                mismatch_examples, key=lambda item: item["file"]),
            "note": (
                "module-prefix-mismatch means the file and its principal class "
                "share the same words but differ in order or carry a module "
                "prefix, e.g. quick_adaptive_capture_source.hpp vs "
                "AdaptiveQuickCaptureSource."
            ),
        },
        "machine_checks": {
            "case_insensitive_path_collisions": case_collisions,
            "duplicate_type_names_across_namespace_or_layer": duplicates,
            "qt_owned_types": sorted(qt_type_first),
            "qt_owned_type_count": len(qt_type_first),
            "qt_plugin_metadata_files": sorted(set(qt_plugin_metadata_files)),
            "public_abi_sensitive_items": public_sensitive,
            "public_installed_headers": sorted(public_headers),
            "install_rules": sorted(set(install_rules)),
            "private_headers": sorted(set(private_headers)),
            "private_headers_with_p_suffix": private_p_suffix,
            "public_header_private_include_leaks": leaks,
            "include_guard": dict(sorted(guard_stats.items())),
            "moc_source_files": sorted(set(moc_files)),
            "automoc_cmake_files": sorted(set(automoc_files)),
            "cmake_targets": sorted(cmake_targets),
            "cmake_options_and_macros": sorted(cmake_options),
            "export_macros": sorted(export_macros),
            "ctest_identities": sorted(ctest_identities),
            "ctest_identity_count": len(ctest_identities),
            "qml_registrations": qml_registrations,
            "plugin_tokens": sorted(plugin_token_first),
            "c_api_symbols": sorted(c_api_first),
            "rfb_wire_files": sorted(set(wire_files)),
        },
        "doc_references": {
            token: {"count": info["count"], "files": sorted(info["files"])}
            for token, info in sorted(doc_refs.items())
        },
        "migration_boundaries": {
            "A_full_breaking_rename": {
                "rows": renamable + by_phase[FROZEN_PHASE],
                "description": "Renames every own symbol and every frozen "
                               "build/QML/plugin/C-ABI contract.",
            },
            "B_public_compatible_internal_first": {
                "rows": by_phase["P1"] + by_phase["P2"] + by_phase["P3"],
                "description": "Freezes installed SDK, QML URI, plugin tokens "
                               "and CMake/test/wire identities; normalizes "
                               "private and internal symbols only.",
            },
            "C_new_files_only": {
                "rows": 0,
                "description": "No existing symbol is renamed; the convention "
                               "applies only to newly created files.",
            },
        },
        "notes": [
            "No Qt build, no CTest and no RealVNC matrix was started by this tool.",
            "No absolute local path is stored; all paths are repo-relative POSIX.",
            "TEST_PLAN=READ_ONLY; this tool is report-only and not registered in CI.",
            "The generator source is archived in the inventory JSON; P0 adds "
            "no tracked executable script.",
        ],
    }
    inventory = {
        "schema": "hy-naming-inventory/v0.1",
        "issue": 969,
        "phase": "P0",
        "test_plan": "READ_ONLY",
        "base_sha": base_sha,
        "required_columns": REQUIRED_FIELDS,
        "columns": FIELDS,
        "row_count": len(rows),
        "rows": rows,
        "generator_source": Path(__file__).read_text(encoding="utf-8"),
    }
    return inventory, summary, all_paths, scope


def validate(inventory, summary, all_paths):
    assert list(inventory["columns"])[:12] == REQUIRED_FIELDS
    for row in inventory["rows"]:
        assert set(FIELDS).issubset(row.keys()), "missing column in row"
        assert all(row[field] != "" for field in REQUIRED_FIELDS), "empty required field"
        assert is_repo_relative(row["current_file"]) or row["current_file"] == "docs/", \
            row["current_file"]
    data_only = {k: v for k, v in inventory.items() if k != "generator_source"}
    blob = json.dumps(data_only, sort_keys=True) + json.dumps(summary, sort_keys=True)
    assert not re.search(r"[A-Za-z]:[\\/]", blob), "absolute Windows path leaked"
    assert "C:\\Qt" not in blob and "C:/Qt" not in blob
    src_cpp = [p for p in all_paths if p.startswith("src/")
               and (Path(p).suffix in CPP_EXT or p.endswith("CMakeLists.txt")
                    or Path(p).suffix in (".qml", ".json"))]
    listed = {row["current_file"] for row in inventory["rows"]}
    missing = [p for p in src_cpp if p not in listed]
    assert not missing, "uncovered src files: %s" % missing[:5]
    return {"src_cpp_cmake_qml_files": len(src_cpp), "uncovered": len(missing)}


def self_test():
    assert to_hy("RemoteAccess") == "HyRemoteAccess"
    assert to_hy("HyFrame") == "HyFrame"
    assert hy_stem("HyRemoteAccess") == "hyremoteaccess"
    assert hy_stem("CaptureSource") == "hycapturesource"
    assert snake("AdaptiveQuickCaptureSource") == "adaptive_quick_capture_source"
    assert snake("QmlRemoteAccess") == "qml_remote_access"
    assert legacy_match("quick_target", "QuickTarget")
    assert legacy_match("QmlRemoteAccess", "QmlRemoteAccess")
    assert not legacy_match("quick_target", "RemoteAccess")
    assert is_qt_type("QQuickWindow")
    assert is_qt_type("QQmlParserStatus")
    assert not is_qt_type("QmlRemoteAccess")
    assert not is_qt_type("QML_NAMED_ELEMENT")
    assert propose_for("RemoteAccess", "public_type") == (
        "HyRemoteAccess", "hyremoteaccess.h")
    assert propose_for("QQuickWindow", "third_party_type") == (
        "unchanged", "unchanged")
    assert propose_for("HYREMOTE_BUILD_TESTS", "cmake_option") == (
        "unchanged", "unchanged")
    assert propose_for("Impl", "pimpl", owner="RemoteAccess") == (
        "HyRemoteAccessPrivate", "hyremoteaccess_p.h")
    assert resolve_main_class("quick_target", {"quick_target": "QuickTarget"}) == (
        "QuickTarget", "legacy-conformant")
    assert resolve_main_class(
        "quick_adaptive_capture_source",
        {"adaptive_quick_capture_source": "AdaptiveQuickCaptureSource"}) == (
            "AdaptiveQuickCaptureSource", "module-prefix-mismatch")
    assert resolve_main_class("rfb_trle", {}) == (None, "no-primary-class")
    assert decide("cmake_option", "build", "build")[5] == FROZEN_PHASE
    assert decide("public_type", "integrations-cpp", "public-installed")[5] == \
        "human-decision"
    assert is_repo_relative("src/core/include/hyremote/core/frame.hpp")
    assert not is_repo_relative("C:/Qt/6.8.3/Src/qtbase/qobject.h")
    assert not is_repo_relative("/usr/local/src/x.cpp")
    assert is_safe_output_dir("docs/internal")
    assert not is_safe_output_dir("tmp")
    assert not is_safe_output_dir("src")
    for bad in ("", "remoteAccess", "9Foo", "Remote-Access"):
        try:
            to_hy(bad)
            raise AssertionError("invalid symbol accepted: %r" % bad)
        except ValueError:
            pass
    assert not is_safe_output_dir("C:/workspace/tmp")
    print("self-test: 30 positive and 5 negative checks passed")
    return 0


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--root", type=Path,
                        default=Path(__file__).resolve().parents[2])
    parser.add_argument("--out", default="docs/internal",
                        help="repo-relative output directory")
    parser.add_argument("--base-sha", default=None)
    parser.add_argument("--self-test", action="store_true")
    args = parser.parse_args()

    if args.self_test:
        return self_test()
    if not is_safe_output_dir(args.out):
        print("refusing unsafe output directory: %s" % args.out, file=sys.stderr)
        return 2

    root = args.root.resolve()
    if not (root / "src").is_dir():
        print("not a HyRemote root: %s" % root, file=sys.stderr)
        return 2
    base_sha = args.base_sha or subprocess.run(
        ["git", "rev-parse", "HEAD"], cwd=str(root), capture_output=True,
        text=True, check=True).stdout.strip()

    inventory, summary, all_paths, scope = collect(root, base_sha)
    summary["coverage"] = validate(inventory, summary, all_paths)
    summary["counts"]["scanned_files"] = len(scope)

    out_dir = root / args.out
    with (out_dir / "hy-naming-inventory.csv").open(
            "w", encoding="utf-8", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=FIELDS, lineterminator="\n")
        writer.writeheader()
        for row in inventory["rows"]:
            writer.writerow(row)
    (out_dir / "hy-naming-inventory.json").write_text(
        json.dumps(inventory, indent=2, sort_keys=True, ensure_ascii=True) + "\n",
        encoding="utf-8")
    (out_dir / "hy-naming-audit-summary.json").write_text(
        json.dumps(summary, indent=2, sort_keys=True, ensure_ascii=True) + "\n",
        encoding="utf-8")

    print("base_sha=%s" % base_sha)
    print("tracked=%d scanned=%d rows=%d" % (
        len(all_paths), len(scope), inventory["row_count"]))
    print("own_types=%d hy_prefixed=%d violation_rate=%s" % (
        summary["conformance"]["own_cxx_types"],
        summary["conformance"]["hy_prefixed_types"],
        summary["conformance"]["hy_prefix_violation_rate"]))
    print("own_src_files=%d with_primary_class=%d mapping=%s" % (
        summary["conformance"]["own_src_cxx_files"],
        summary["conformance"]["files_with_primary_class"],
        summary["file_mapping"]["breakdown"]))
    print("case_collisions=%d qt_types=%d ctest_identities=%d" % (
        len(summary["machine_checks"]["case_insensitive_path_collisions"]),
        summary["machine_checks"]["qt_owned_type_count"],
        summary["machine_checks"]["ctest_identity_count"]))
    print("outputs: %s" % args.out)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
